style.css:
@-moz-document domain("weverse.io") {
/* ========== MAIN BACKGROUND (FULL FIX) ========== */
    html,
    body,
    #root,
    main,
    .layout,
    .content,
    .container,
    .page,
    .wrapper,
    [class*="layout"],
    [class*="container"],
    [class*="wrapper"],
    [class*="page"],
    [class*="content"] {
        background-color: #ffaac1ba !important;
        color: #4a2b35 !important;
    }

    /* ========== SIDEBAR (GROUP LIST) ========== */
    aside,
    .sidebar,
    .sidebar-wrapper,
    .group-list,
    .menu,
    [class*="sidebar"] {
        background-color: #ff96b2ba !important;
        border-right: 1px solid rgba(255, 255, 255, 0.4) !important;
    }

    /* ========== TOP NAV BAR (FULL FIX) ========== */
    header,
    .top-bar,
    .navigation,
    .tabs,
    .tab-menu,
    [class*="tab"],
    [class*="menu"],
    [class*="navigation"],
    [class*="nav"],
    [class*="category"],
    [class*="filter"],
    [class*="segment"] {
        background-color: #ffbcceba !important;
        border-bottom: 1px solid rgba(255,255,255,0.4) !important;
    }

    /* ACTIVE TAB — REMOVES RED */
    [class*="active"],
    [class*="selected"] {
        color: #ff6f9c !important;
        border-bottom: 2px solid #ff6f9c !important;
    }

    /* GLOBAL RED OVERRIDE */
    *[style*="red"],
    *[class*="red"] {
        color: #ff6f9c !important;
        background-color: transparent !important;
        border-color: #ff6f9c !important;
    }

    /* ========== POSTS / FEED CARDS ========== */
    .post,
    .feed-item,
    .card,
    article,
    [class*="post"],
    [class*="card"] {
        background-color: rgba(255, 255, 255, 0.75) !important;
        border-radius: 14px !important;
        border: 1px solid rgba(255, 170, 193, 0.4) !important;
        box-shadow: 0 4px 12px rgba(255, 150, 178, 0.25) !important;
    }

    /* ========== BUTTONS ========== */
    button,
    .btn,
    [class*="button"] {
        background-color: #ff96b2ba !important;
        color: white !important;
        border-radius: 12px !important;
        border: none !important;
        transition: 0.2s ease !important;
    }

    button:hover,
    .btn:hover,
    [class*="button"]:hover {
        background-color: #ff7fa5 !important;
    }

    /* ========== LINKS & HIGHLIGHTS ========== */
    a,
    .highlight {
        color: #ff6f9c !important;
    }

    /* ========== INPUT BOXES & SEARCH ========== */
    input,
    textarea,
    .input,
    .search,
    [class*="input"],
    [class*="search"] {
        background-color: rgba(255, 255, 255, 0.9) !important;
        border: 1px solid rgba(255, 150, 178, 0.6) !important;
        border-radius: 12px !important;
    }

    /* ========== SCROLLBAR (CHROME / OPERA GX) ========== */
    ::-webkit-scrollbar {
        width: 10px;
    }

    ::-webkit-scrollbar-track {
        background: #ffd6e2;
    }

    ::-webkit-scrollbar-thumb {
        background: #ff96b2;
        border-radius: 10px;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #ff7fa5;
    }
}
